def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    axes = [
        lambda r, c: r,
        lambda r, c: c,
        lambda r, c: r + c,
        lambda r, c: c - r,
    ]

    # The marked diagonals/rows indicate the coordinate along which the
    # repeating bands are arranged.
    def axis_score(axis):
        groups = {}
        for r, c, color in cells:
            key = axis(r, c)
            groups.setdefault(key, []).append(color)
        return max((len(v) for v in groups.values()), default=0)

    axis = max(axes, key=axis_score)

    mapping = None
    for period in range(1, max(h, w) + 1):
        trial = {}
        valid = True
        for r, c, color in cells:
            residue = axis(r, c) % period
            if residue in trial and trial[residue] != color:
                valid = False
                break
            trial[residue] = color
        if valid:
            mapping = trial
            break

    if mapping is None:
        # Fallback: extend each marked color band by its coordinate residue.
        mapping = {}
        for r, c, color in cells:
            mapping[axis(r, c)] = color
        keys = sorted(mapping)

        def color_at(x):
            return mapping[min(keys, key=lambda k: abs(k - x))]

        return [[color_at(axis(r, c)) for c in range(w)] for r in range(h)]

    # Fill any residues not explicitly represented by continuing the
    # repeating sequence from the nearest represented residue.
    residues = sorted(mapping)

    def color_at(x):
        residue = x % period
        if residue in mapping:
            return mapping[residue]
        nearest = min(residues, key=lambda q: min((residue - q) % period, (q - residue) % period))
        return mapping[nearest]

    return [[color_at(axis(r, c)) for c in range(w)] for r in range(h)]
