def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c] != 0]

    # The colored diagonal strokes encode repeating diagonal bands.
    # For this orientation, the band coordinate is column minus row.
    coord = lambda r, c: c - r
    for period in range(1, 2 * max(h, w) + 1):
        bands = {}
        valid = True
        for r, c, color in points:
            k = coord(r, c) % period
            if k in bands and bands[k] != color:
                valid = False
                break
            bands[k] = color
        if valid:
            break

    known = list(bands)

    def band_color(k):
        k %= period
        if k in bands:
            return bands[k]
        nearest = min(known,
                      key=lambda q: (min((k - q) % period, (q - k) % period), q))
        return bands[nearest]

    return [[band_color(coord(r, c)) for c in range(w)] for r in range(h)]
